const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demoCode="function subtotal(price, quantity) {\n  return price * quantity;\n}\n\nfunction delivery(total) {\n  if (total >= 10000) return 0;\n  return 1000;\n}\n\nfunction discount(total, isMember) {\n  if (isMember && total > 5000) return total * 0.9;\n  return total;\n}\n\nfunction orderTotal(price, quantity, isMember) {\n  const total = subtotal(price, quantity);\n  return discount(total, isMember) + delivery(total);\n}\n";
const demoTests=[{name:'Обычный заказ',expression:'orderTotal(1000,2,false)',expected:3000},{name:'Бесплатная доставка на границе',expression:'delivery(10000)',expected:0},{name:'Доставка ниже порога',expression:'delivery(9999)',expected:1000},{name:'Скидка участнику',expression:'discount(6000,true)',expected:5400},{name:'Без скидки для гостя',expression:'discount(6000,false)',expected:6000},{name:'Итог с бесплатной доставкой',expression:'orderTotal(6000,2,false)',expected:12000}];
let files={'order.js':demoCode},tests=structuredClone(demoTests),state=null,current='order.js',busy=false;
const isAuditor=new URLSearchParams(location.search).has('auditor'),channel=new BroadcastChannel('tusinu-audit-v1');
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',6500);}
function view(id){if(isAuditor)id='auditor';document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===id));$('#breadcrumb').innerHTML='Рабочее пространство <span>/ '+({setup:'Новый аудит',workspace:'Защита',report:'Результат',auditor:'Аудитор'}[id])+'</span>';}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>view(b.dataset.view));
function codeOf(f){return Object.keys(f).sort().map(k=>f[k]).join('\n;\n');}
function execute(f,t){return new Promise(resolve=>{const source="self.fetch=undefined;self.XMLHttpRequest=undefined;self.WebSocket=undefined;self.importScripts=undefined;self.onmessage=async e=>{try{const {code,tests}=e.data;const fn=new Function(code+'\\nreturn ['+tests.map(t=>'('+t.expression+')').join(',')+'];');const values=await Promise.all(fn());self.postMessage({results:values.map((v,i)=>({name:tests[i].name,pass:JSON.stringify(v)===JSON.stringify(tests[i].expected),actual:v,expected:tests[i].expected}))});}catch(err){self.postMessage({error:err.message});}};";
 const url=URL.createObjectURL(new Blob([source],{type:'text/javascript'})),worker=new Worker(url);let done=false;const finish=x=>{if(done)return;done=true;clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);resolve(x);};const timer=setTimeout(()=>finish({error:'Превышено время выполнения (2 секунды)'}),2000);worker.onmessage=e=>finish(e.data);worker.onerror=e=>{e.preventDefault();finish({error:e.message||'Ошибка выполнения'});};worker.postMessage({code:codeOf(f),tests:t});});}
function validateTests(t){if(!Array.isArray(t)||!t.length||t.length>100)throw Error('Нужно от 1 до 100 тестов');for(const x of t)if(typeof x.name!=='string'||typeof x.expression!=='string'||!('expected'in x))throw Error('У теста нужны name, expression и expected');}
async function upload(list){if(state?.active||busy)return toast('Дождитесь завершения текущей операции');try{if(!list.length)return;let next={},newTests=null,total=0;for(const f of list){total+=f.size;if(total>1e6)throw Error('Общий размер больше 1 МБ');if(f.name==='tests.json'){newTests=JSON.parse(await f.text());validateTests(newTests);}else if(f.name.endsWith('.js')){if(next[f.name])throw Error('Одинаковые имена файлов');next[f.name]=await f.text();}else throw Error('Поддерживаются .js и tests.json');}if(!Object.keys(next).length||!newTests)throw Error('Загрузите .js файлы и tests.json вместе');files=next;tests=newTests;state=null;$('#files-status').textContent='Загружено: '+Object.keys(files).length+' файлов · '+tests.length+' тестов';toast('Проект загружен');}catch(e){toast(e.message);}}
$('#upload').onchange=e=>upload([...e.target.files]);$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{e.preventDefault();upload([...e.dataTransfer.files]);};
$('#demo').onclick=()=>{if(state?.active||busy)return toast('Сначала завершите текущую операцию');files={'order.js':demoCode};tests=structuredClone(demoTests);state=null;$('#files-status').textContent='Демо-проект: расчёт заказа · 6 тестов';toast('Демонстрационный проект восстановлен');};
function sync(){if(!isAuditor&&state)channel.postMessage({type:'state',state});}
function addLog(text){state.log.push({time:new Date().toLocaleTimeString('ru-RU'),text});sync();}
function saveEditor(){if(state&&current)state.edited[current]=$('#editor').value;}
function renderFiles(){const keys=Object.keys(state.edited);if(!keys.includes(current))current=keys[0];$('#file-list').innerHTML=keys.map(k=>'<button data-file="'+esc(k)+'" class="'+(k===current?'selected':'')+'">⌘ '+esc(k)+'</button>').join('');$('#filename').textContent=current;$('#editor').value=state.edited[current];$('#file-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{saveEditor();current=b.dataset.file;renderFiles();});const a=state.analysis;$('#analysis').innerHTML=a.files+' файлов<br>'+a.functions+' функций<br>'+a.conditions+' условий<br>'+a.loops+' циклов';}
$('#prepare').onclick=async()=>{if(busy)return;if(state?.active)return toast('Сначала завершите текущую защиту');busy=true;$('#prepare').disabled=true;$('#prepare').textContent='Анализ и проверка…';try{validateTests(tests);const baseline=await execute(files,tests);if(baseline.error)throw Error('Исходный проект: '+baseline.error);if(baseline.results.some(t=>!t.pass))throw Error('Исходный проект должен проходить все тесты');const analysis=MutationEngine.analyze(files),selected=[];for(const m of analysis.candidates.slice(0,80)){if(selected.some(x=>x.file===m.file&&x.line===m.line))continue;const result=await execute(MutationEngine.mutate(files,[m]),tests);if(!result.error&&result.results.some(t=>!t.pass)){selected.push({...m,testIndexes:result.results.flatMap((t,i)=>t.pass?[]:[i])});if(selected.length===3)break;}}if(selected.length!==3)throw Error('Не удалось найти 3 проверяемые мутации на разных строках. Добавьте условия и граничные тесты.');const mutated=MutationEngine.mutate(files,selected),check=await execute(mutated,tests);if(check.error||check.results.every(x=>x.pass))throw Error('Комбинация мутаций не подходит. Измените набор тестов.');state={id:crypto.randomUUID(),original:structuredClone(files),edited:mutated,tests:structuredClone(tests),mutations:selected,analysis,active:false,finished:false,start:null,deadline:null,results:[],notes:[],log:[],runs:0};addLog('Аудит подготовлен: 3 проверенные мутации');renderFiles();$('#session-state').textContent='Готово к защите · 3 мутации';$('#start').disabled=false;$('#editor').disabled=true;$('#run').disabled=true;$('#finish').disabled=true;$('#test-results').textContent='Нажмите «Начать защиту», чтобы открыть редактор.';view('workspace');toast('Аудит готов. Откройте экран аудитора перед стартом.');}catch(e){toast(e.message);}finally{busy=false;$('#prepare').disabled=false;$('#prepare').innerHTML='Создать аудит <span>↗</span>';}};
$('#start').onclick=()=>{if(!state||state.active||state.finished)return;state.active=true;state.start=Date.now();state.deadline=state.start+600000;$('#editor').disabled=false;$('#explanation').disabled=false;$('#explanation').value='';$('#record').disabled=false;$('#start').disabled=true;$('#run').disabled=false;$('#finish').disabled=false;$('#session-state').textContent='Защита идёт · без LLM-помощников';addLog('Началась 10-минутная защита');$('#editor').focus();};
$('#editor').oninput=()=>{if(!state?.active)return;saveEditor();sync();};
$('#editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target;t.setRangeText('  ',t.selectionStart,t.selectionEnd,'end');saveEditor();sync();}};
function renderTests(result){$('#test-results').innerHTML=result.error?'<p class="fail">'+esc(result.error)+'</p>':result.results.map(t=>'<div class="test-row"><span>'+esc(t.name)+'</span><span class="'+(t.pass?'pass':'fail')+'">'+(t.pass?'✓ Пройден':'✕ Ожидалось '+esc(JSON.stringify(t.expected))+', получено '+esc(JSON.stringify(t.actual)))+'</span></div>').join('');}
$('#run').onclick=async()=>{if(!state?.active||busy)return;if(Date.now()>=state.deadline)return finish();saveEditor();busy=true;$('#run').disabled=true;const id=state.id,revision=codeOf(state.edited),r=await execute(state.edited,state.tests);if(state?.id===id&&!state.finished){state.runs++;if(codeOf(state.edited)===revision){state.results=r.results||[];state.error=r.error||null;state.checkedCode=revision;renderTests(r);addLog('Тесты: '+(r.error||r.results.filter(t=>t.pass).length+'/'+tests.length));}else toast('Код изменился во время проверки. Запустите тесты ещё раз.');}busy=false;$('#run').disabled=!state?.active;};
$('#record').onclick=()=>{if(!state?.active)return;const text=$('#explanation').value.trim();if(!text)return toast('Опишите найденную ошибку');state.notes.push({text,time:new Date().toLocaleTimeString('ru-RU')});$('#explanation').value='';addLog('Студент зафиксировал наблюдение');toast('Наблюдение записано');};
async function finish(){if(!state?.active||state.finished)return;state.active=false;state.finished=true;state.end=Date.now();saveEditor();$('#editor').disabled=true;$('#run').disabled=true;$('#finish').disabled=true;$('#record').disabled=true;$('#explanation').disabled=true;addLog('Защита завершена');const result=await execute(state.edited,state.tests);state.results=result.results||[];state.error=result.error||null;state.checkedCode=codeOf(state.edited);renderTests(result);renderReport();sync();view('report');}
$('#finish').onclick=finish;
setInterval(()=>{if(isAuditor||!state?.active)return;const left=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));$('#timer').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');$('#timer').classList.toggle('danger',left<=60);if(!left)finish();},250);
function mutationStatus(m){if(state.error||state.checkedCode!==codeOf(state.edited))return 'Проверка не завершена';return m.testIndexes.every(i=>state.results[i]?.pass)?'Связанные тесты пройдены':'Связанные тесты не пройдены';}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderReport(){if(!state?.finished)return;const passed=state.results.filter(t=>t.pass).length,restored=state.mutations.filter(m=>mutationStatus(m)==='Связанные тесты пройдены').length;$('#report-content').innerHTML='<div class="stats"><div><b>'+passed+'/'+state.tests.length+'</b><span>Тестов пройдено</span></div><div><b>'+restored+'/3</b><span>Мутаций по тестам</span></div><div><b>'+Math.min(600,Math.round((state.end-state.start)/1000))+'с</b><span>Время защиты</span></div></div><h2>'+(passed===state.tests.length?'Поведение восстановлено по всем тестам':'Есть ошибки для обсуждения')+'</h2><p class="muted">Результат отражает покрытие загруженных тестов. Понимание и найденные причины подтверждает аудитор в обсуждении.</p>'+(state.error?'<p class="fail">'+esc(state.error)+'</p>':'')+state.mutations.map((m,i)=>'<div class="mutation"><strong>0'+(i+1)+' / '+esc(m.kind)+'</strong><p>'+esc(m.file)+' : '+m.line+' &nbsp; <code>'+esc(m.before)+'</code> заменено на <code>'+esc(m.after)+'</code></p><span>'+mutationStatus(m)+'</span></div>').join('')+'<h2>Наблюдения студента</h2>'+(state.notes.map(n=>'<p>'+esc(n.text)+'</p>').join('')||'<p class="muted">Наблюдения не зафиксированы</p>')+'<div class="report-actions"><button class="primary" id="export-report">Скачать отчёт JSON</button><button class="secondary" id="download-code">Скачать исправленные файлы</button><button class="secondary" id="again">Новый аудит</button></div>';$('#export-report').onclick=()=>download('tusinu-report.json',JSON.stringify({...state,notice:'Локальный прототип. Оценка по тестам, понимание подтверждает аудитор.'},null,2));$('#download-code').onclick=()=>Object.entries(state.edited).forEach(([name,text])=>download(name,text));$('#again').onclick=()=>view('setup');}
function drawAuditor(){if(!state)return;$('#auditor-content').innerHTML='<div class="stats"><div><b>'+(state.active?'LIVE':state.finished?'FINISH':'READY')+'</b><span>Состояние</span></div><div><b>'+state.runs+'</b><span>Запусков тестов</span></div><div><b>'+state.results.filter(x=>x.pass).length+'/'+state.tests.length+'</b><span>Последняя проверка</span></div></div><p class="muted">'+(state.active?'Осталось: '+Math.max(0,Math.ceil((state.deadline-Date.now())/1000))+' секунд':'Ожидание или завершение защиты')+'</p><h2>Карта мутаций</h2>'+state.mutations.map(m=>'<div class="mutation"><strong>'+esc(m.file)+' : '+m.line+'</strong><p>'+esc(m.kind)+' &nbsp; <code>'+esc(m.before)+'</code> заменено на <code>'+esc(m.after)+'</code></p><span>'+mutationStatus(m)+'</span></div>').join('')+'<h2>Редактор студента</h2>'+Object.entries(state.edited).map(([k,v])=>'<p>'+esc(k)+'</p><pre class="audit-code">'+esc(v)+'</pre>').join('')+'<h2>Наблюдения</h2>'+state.notes.map(n=>'<p>'+esc(n.time)+' · '+esc(n.text)+'</p>').join('')+'<h2>Журнал</h2><div class="log">'+state.log.map(l=>esc(l.time)+' · '+esc(l.text)).join('<br>')+'</div>';}
channel.onmessage=e=>{if(isAuditor&&e.data.type==='state'){state=e.data.state;drawAuditor();}else if(e.data.type==='request')sync();};
$('#auditor-open').onclick=()=>window.open(location.pathname+'?auditor=1','tusinu-auditor');
if(isAuditor){view('auditor');channel.postMessage({type:'request'});setInterval(drawAuditor,1000);}else view('setup');
